$errors=[]; $nama=trim((string)($_POST['nama']??'')); $nip=trim((string)($_POST['nip']??'')); $jk=(string)($_POST['jk']??''); $no_hp=trim((string)($_POST['no_hp']??'')); $mapel=trim((string)($_POST['mapel']??'')); $status=(string)($_POST['status']??'aktif');
if($_SERVER['REQUEST_METHOD']==='POST'){ require_valid_csrf(); if($nama==='')$errors[]='Nama guru wajib diisi.'; if(!in_array($jk,['','L','P'],true))$errors[]='Jenis kelamin tidak valid.'; if(!in_array($status,['aktif','nonaktif'],true))$errors[]='Status tidak valid.'; if(!$errors){try{$qr=guru_generate_qr($pdo);$st=$pdo->prepare("INSERT INTO guru (nama,nip,jk,no_hp,kode_qr,mapel,status) VALUES (?,NULLIF(?,''),NULLIF(?,''),NULLIF(?,''),?,?,?)");$st->execute([$nama,$nip,$jk,$no_hp,$qr,$mapel,$status]);$id=(int)$pdo->lastInsertId();guru_audit($pdo,'CREATE',$id,'Menambahkan guru '.$nama);redirect('guru/detail.php?id='.$id.'&saved=1');}catch(PDOException $e){if((int)($e->errorInfo[1]??0)===1062)$errors[]='NIP sudah digunakan.';else throw $e;}}}
